/*
 * A313898  Coordination sequence Gal.5.291.2 where Gal.u.t.v denotes the
 *          coordination sequence for a vertex of type v in tiling number t in
 *          the Galebach list of u-uniform tilings.
 * https://oeis.org/A313898
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 5*n + k(n) where k(n) is the number of terms generated by
 *            the periodic step sequence {2,1,2,5} starting from position 3
 *            that are <= n
 * Range:     u8 n <= 47, u16 n <= 49, u32 n <= 49, u64 n <= 49, u128 n <= 49,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)1;          /* a(0) = 1 */

    idx_t offset = 0;              /* k(n) */
    idx_t pos = 3;                 /* current position */
    const idx_t steps[4] = {2, 1, 2, 5};
    idx_t step_idx = 0;

    while (pos <= n) {
        offset++;                  /* increment k(n) */
        pos += steps[step_idx];    /* advance to next position */
        step_idx = (step_idx + 1) & 3; /* cycle through 0..3 */
    }

    seq_t result = (seq_t)5 * (seq_t)n + (seq_t)offset;
    return result;
}
